-- Specialised MCQ items (welding_inspector): gas-transmission pipelines, PRS/CGS, CP, metering and compressor stations. Sources are named in standard_ref.
-- Added 2026-10-15; approved by owner instruction (no manual review).
insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, item_type, answer_key, explanation_fa, standard_ref, approval_status, active)
select v.job_role, 'TECHNICAL', v.topic, v.difficulty, v.stem_fa, v.options, v.correct_option, v.item_type, v.answer_key, v.explanation_fa, v.standard_ref, 'APPROVED', true
from (values
  ('welding_inspector', 'معیار پذیرش API 1104', 2, 'طبق API 1104، نفوذ ناقص ریشه (IP) منفرد با طول ۴۰ میلی‌متر در یک جوش محیطی چه وضعیتی دارد؟', '["قابل قبول است، چون طول آن از ۵۰ میلی‌متر کمتر است","مردود است، چون طول منفرد IP از ۲۵ میلی‌متر بیشتر است","قابل قبول است و باید در گزارش روزانه ثبت شود","مردود است، ولی در صورت ضخامت دیواره بیش از ۲۰ میلی‌متر"]'::jsonb, 1, 'SINGLE', null, 'در API 1104 طول منفرد IP بیش از ۲۵ mm (۱ in) مردود است؛ مجموع طول IP نیز در هر ۳۰۰ mm از جوش نباید از ۲۵ mm و در جوش‌های کوتاه‌تر از ۳۰۰ mm از ۸٪ طول جوش بیشتر شود.', 'API 1104 (Welding of Pipelines and Related Facilities) – بخش معیار پذیرش رادیوگرافی'),
  ('welding_inspector', 'معیار پذیرش API 1104', 2, 'ترک در جوش خط لوله طبق API 1104 چگونه ارزیابی می‌شود؟', '["قابل قبول است اگر طول آن کمتر از ۱۰ میلی‌متر باشد","قابل قبول است اگر در ناحیه HAZ و نه در فلز جوش باشد","مردود است، مگر ترک‌های کراتر یا ستاره‌ای کم‌عمق تا ۴ میلی‌متر","مردود است، مگر در جوش‌هایی که فشار کاری کمتر از ۳۰ بار دارند"]'::jsonb, 2, 'SINGLE', null, 'ترک صرف‌نظر از طول و محل مردود است؛ تنها استثنا ترک‌های کراتر/ستاره‌ای کم‌عمق با طول حداکثر ۴ mm (۵/۳۲ in) است.', 'API 1104 (Welding of Pipelines and Related Facilities)'),
  ('welding_inspector', 'معیار پذیرش API 1104', 2, 'اندازهٔ حفرهٔ گازی منفرد (Porosity) در جوش خط لوله حداکثر چقدر مجاز است؟', '["۶ میلی‌متر و ۵۰٪ ضخامت نازک‌تر","۱٫۵ میلی‌متر و ۱۰٪ ضخامت نازک‌تر","۵ میلی‌متر مستقل از ضخامت دیواره لوله","۳ میلی‌متر و ۲۵٪ ضخامت نازک‌تر"]'::jsonb, 3, 'SINGLE', null, 'برای تخلخل منفرد، قطر بیش از ۱/۸ in (۳ mm) یا بیش از ۲۵٪ ضخامت اسمی نازک‌تر قطعه مردود است.', 'API 1104 (Welding of Pipelines and Related Facilities)'),
  ('welding_inspector', 'معیار پذیرش API 1104', 3, 'حد طول منفرد مردودی برای عدم ذوب (IF) و عدم ذوب ناشی از لب‌پریدگی سرد (IFD) در API 1104 به‌ترتیب چقدر است؟', '["IF برابر ۲۵ و IFD برابر ۵۰ میلی‌متر","IF برابر ۵۰ و IFD برابر ۲۵ میلی‌متر","هر دو برابر ۵۰ میلی‌متر","هر دو برابر ۱۳ میلی‌متر"]'::jsonb, 0, 'SINGLE', null, 'IF منفرد بیش از ۱ in (۲۵ mm) و IFD منفرد بیش از ۲ in (۵۰ mm) مردود است.', 'API 1104 (Welding of Pipelines and Related Facilities)'),
  ('welding_inspector', 'معیار پذیرش API 1104', 2, 'در جوش‌های کوتاه‌تر از ۳۰۰ میلی‌متر، مجموع طول نفوذ ناقص (IP) حداکثر چند درصد طول جوش مجاز است؟', '["۱۲٪","۸٪","۴٪","۲۵٪"]'::jsonb, 1, 'SINGLE', null, 'علاوه بر حد ۲۵ mm در هر ۳۰۰ mm، مجموع IP در جوش کوتاه‌تر از ۳۰۰ mm نباید از ۸٪ طول جوش بیشتر شود.', 'API 1104 (Welding of Pipelines and Related Facilities)'),
  ('welding_inspector', 'تعمیر جوش', 2, 'در یک جوش محیطی، ترکی به طول بیش از ۸٪ طول جوش کشف شده است. اقدام صحیح چیست؟', '["تعمیر موضعی ترک با سنگ‌زنی و جوشکاری مجدد","پذیرش جوش با ثبت NCR و پایش در تست هیدرواستاتیک","قطع و برداشتن کل جوش (Cut-out) و اجرای مجدد","تعمیر با پاس پوششی (Cap pass) روی ناحیه ترک"]'::jsonb, 2, 'SINGLE', null, 'طبق API 1104 ترک‌های بلندتر از ۸٪ طول جوش قابل تعمیر نیست و کل جوش باید قطع شود.', 'API 1104 (Welding of Pipelines and Related Facilities) – بخش تعمیر و برداشتن عیوب'),
  ('welding_inspector', 'تعمیر جوش', 2, 'پیش‌نیاز اجرای تعمیر جوش در خط لوله کدام است؟', '["حکم شفاهی سرپرست جوشکاری و ثبت در گزارش روزانه","استفاده از همان جوشکار اولیه و روش ذهنی او","تعمیر بلافاصله پس از تست هیدرواستاتیک خط","Repair WPS تأییدشده و بازرسی مجدد ناحیه"]'::jsonb, 3, 'SINGLE', null, 'تعمیر باید با روش مکتوب و واجد صلاحیت انجام و ناحیه تعمیرشده با روش NDT اولیه دوباره بازرسی شود.', 'API 1104 (Welding of Pipelines and Related Facilities) – بخش تعمیر'),
  ('welding_inspector', 'متالورژی جوش', 2, 'هدف اصلی پیش‌گرم قبل از جوشکاری فولاد X65 چیست؟', '["کاهش نرخ سرد شدن و ترک هیدروژنی HAZ","افزایش نفوذ جوش و حذف نیاز به پاس ریشه","حذف تنش پسماند پس از پایان جوشکاری","افزایش سختی HAZ برای بهبود مقاومت سایشی"]'::jsonb, 0, 'SINGLE', null, 'پیش‌گرم نرخ سرد شدن را کم و خروج هیدروژن را ممکن می‌کند و از تشکیل ریزساختار سخت جلوگیری می‌کند.', 'API 1104 / ASME B31.8 – مبانی جوش‌پذیری'),
  ('welding_inspector', 'متالورژی جوش', 2, 'سه عامل لازم برای وقوع ترک هیدروژنی (سرد) در جوش کدام‌اند؟', '["اکسیژن، فشار فشاری و ریزساختار نرم","هیدروژن، تنش کششی و ریزساختار سخت","رطوبت هوا، دمای زیاد و ضخامت کم","ناخالصی سولفور، دمای صفر و ریزساختار فریتی"]'::jsonb, 1, 'SINGLE', null, 'ترک هیدروژنی هنگام همزمانی هیدروژن محلول، تنش کششی و ساختار حساس (مارتنزیتی/بینیتی) و دمای زیر حدود ۲۰۰°C رخ می‌دهد.', 'AWS D1.1 / EN 1011-2 – ترک سرد'),
  ('welding_inspector', 'جوش‌پذیری', 2, 'فولادی با C=0.12، Mn=1.5، Cr=0.03، Mo=0.02، V=0.05، Ni=0.2 و Cu=0.15 (درصد وزنی) دارد. کربن معادل IIW (CE) تقریباً چند است؟', '["","","",""]'::jsonb, 0, 'NUMERIC', '{"unit":"","value":0.41,"tolPct":2}'::jsonb, 'CE = C + Mn/6 + (Cr+Mo+V)/5 + (Ni+Cu)/15 = 0.12 + 0.25 + 0.02 + 0.0233 ≈ 0.41', 'API 5L / IIW – کربن معادل'),
  ('welding_inspector', 'فلز پرکننده', 2, 'برای پاس ریشهٔ جوشکاری دستی خطوط لولهٔ فولادی با روش رو به پایین (Downhill) معمولاً کدام الکترود به‌کار می‌رود؟', '["E7018 کم‌هیدروژن","E6013 روتیلی","E6010 سلولزی","E308L ضدزنگ"]'::jsonb, 2, 'SINGLE', null, 'الکترود سلولزی E6010 با قوس نفوذی و رفتار مناسب رو به پایین، متداول‌ترین الکترود پاس ریشه در خطوط انتقال است.', 'API 1104 (Welding of Pipelines and Related Facilities)'),
  ('welding_inspector', 'صلاحیت جوشکار', 2, 'در آزمون صلاحیت جوشکار طبق API 1104 برای ضخامت دیواره بیش از ۱۲٫۷ میلی‌متر، به‌جای خمش ریشه و رویه از کدام نمونه استفاده می‌شود؟', '["نمونه ضربه شارپی (Charpy)","نمونه سختی‌سنجی ویکرز","نمونه کشش عرضی بدون خمش","نمونه خمش جانبی (Side bend)"]'::jsonb, 3, 'SINGLE', null, 'برای ضخامت بیش از ۱۲٫۷ mm (۱/۲ in) نمونه‌های خمش جانبی جایگزین خمش ریشه و رویه می‌شوند.', 'API 1104 (Welding of Pipelines and Related Facilities) – بخش صلاحیت جوشکار'),
  ('welding_inspector', 'صلاحیت WPS', 3, 'در API 1104 فولاد با حداقل استحکام تسلیم ۴۴۸ MPa (X65) از نظر گروه مواد پایه چگونه است؟', '["هر گرید ≥ ۶۵۰۰۰ psi جداگانه تأیید می‌شود","در همان گروه X52 قرار می‌گیرد و WPS جدا نمی‌خواهد","در گروه فولادهای کم‌استحکام تا ۴۲۰۰۰ psi قرار می‌گیرد","با یک WPS مشترک برای گریدهای X52 تا X80 کاربرد دارد"]'::jsonb, 0, 'SINGLE', null, 'گروه‌بندی مواد پایه: SMYS ≤ ۴۲۰۰۰ psi؛ بین ۴۲۰۰۰ و ۶۵۰۰۰ psi؛ و گریدهای ≥ ۶۵۰۰۰ psi که هر یک جداگانه تأیید می‌شوند.', 'API 1104 (Welding of Pipelines and Related Facilities) – متغیرهای اساسی WPS'),
  ('welding_inspector', 'جوشکاری خط لوله', 2, 'چرا فاصلهٔ زمانی بین پاس ریشه و پاس داغ در WPS خطوط لوله محدود می‌شود؟', '["چون الکترود پاس داغ پس از چند دقیقه منقضی می‌شود","چون سرد شدن پاس ریشه ترک هیدروژنی را محتمل می‌کند","چون تأخیر زیاد باعث افزایش ارتفاع گرده جوش می‌شود","چون تغییر رنگ پاس ریشه بازرسی چشمی را دشوار می‌کند"]'::jsonb, 1, 'SINGLE', null, 'پاس ریشه نازک است و در صورت تأخیر سرد می‌شود و تحت تنش، مستعد ترک هیدروژنی خواهد بود؛ زمان بین پاس‌ها متغیر اساسی WPS است.', 'API 1104 (Welding of Pipelines and Related Facilities)'),
  ('welding_inspector', 'بازرسی چشمی', 1, 'برای اندازه‌گیری عمق زیرگرفتگی (Undercut) در بازرسی چشمی از چه ابزاری استفاده می‌شود؟', '["ضخامت‌سنج التراسونیک","کولیس برای اندازه‌گیری قطر خارجی لوله","گیج جوش (Cambridge / Bridge cam gauge)","گیج فشار کالیبره با دقت بالا"]'::jsonb, 2, 'SINGLE', null, 'گیج‌های جوش با عمق‌سنج، عمق زیرگرفتگی و ارتفاع گرده را اندازه می‌گیرند.', 'AWS B1.11 / ISO 17637 – بازرسی چشمی'),
  ('welding_inspector', 'معیار پذیرش API 1104', 3, 'کدام مورد برای عمق زیرگرفتگی (Undercut) بیرونی در API 1104 مردود است؟', '["عمق بیش از ۲ میلی‌متر یا ۲۵٪ ضخامت","هر عمقی که با چشم دیده شود","عمق بیش از ۰٫۱ میلی‌متر در طول بیش از ۱۰۰ میلی‌متر","عمق بیش از ۰٫۸ میلی‌متر یا ۱۲٫۵٪ ضخامت (هر کدام کمتر)"]'::jsonb, 3, 'SINGLE', null, 'عمق بیش از ۱/۳۲ in (۰٫۸ mm) یا ۱۲٫۵٪ ضخامت (کمتر) مردود است؛ مقادیر کمتر تابع محدودیت‌های طولی‌اند.', 'API 1104 (Welding of Pipelines and Related Facilities)'),
  ('welding_inspector', 'درصد NDT ASME B31.8', 2, 'طبق ASME B31.8، حداقل درصد جوش‌های محیطی که در هر روز باید به‌صورت تصادفی NDT شوند برای Class 3 چقدر است؟', '["۴۰٪","۱۰٪","۱۵٪","۷۵٪"]'::jsonb, 0, 'SINGLE', null, 'درصد NDT: Class 1: ۱۰٪ ، Class 2: ۱۵٪ ، Class 3: ۴۰٪ ، Class 4: ۷۵٪؛ تقاطع‌ها و اتصالات نهایی ۱۰۰٪.', 'ASME B31.8 – بخش بازرسی جوش'),
  ('welding_inspector', 'صلاحیت پرسنل NDT', 1, 'چه سطحی از صلاحیت برای تفسیر و ارزیابی فیلم رادیوگرافی طبق ISO 9712 / ASNT لازم است؟', '["سطح ۱ (Level I) به‌تنهایی","سطح ۲ (Level II) یا بالاتر","گواهی ایمنی پرتوکار و سابقهٔ کار","مدرک مهندسی مکانیک و سابقهٔ پروژه"]'::jsonb, 1, 'SINGLE', null, 'سطح ۱ فقط تحت نظارت کار می‌کند؛ تفسیر و گزارش نهایی بر عهده سطح ۲ یا ۳ است.', 'ISO 9712 / ASNT SNT-TC-1A'),
  ('welding_inspector', 'جوشکاری مکانیزه', 2, 'عیب شاخص و رایج جوشکاری مکانیزه GMAW (اتصال کوتاه) در خطوط لوله کدام است؟', '["تخلخل کروی در پاس ریشه","ترک گرمایی در فلز پایه","عدم ذوب جانبی دیواره پخ","زیرگرفتگی داخلی ناشی از دمای کم"]'::jsonb, 2, 'SINGLE', null, 'در GMAW با انتقال اتصال کوتاه، ذوب ناکافی دیواره پخ شایع‌ترین عیب است و با تنظیم پارامتر و الگوی حرکت کنترل می‌شود.', 'API 1104 – Annex مکانیزه'),
  ('welding_inspector', 'فلز پرکننده', 1, 'الکترودهای کم‌هیدروژن پس از پخت (Baking) باید چگونه نگهداری شوند؟', '["در قفسهٔ باز کارگاه کنار مصالح دیگر","در جعبهٔ فلزی بسته روی زمین انبار","داخل کیف پلاستیکی در دمای محیط","در آون نگهدارنده حدود ۱۲۰ تا ۱۵۰°C"]'::jsonb, 3, 'SINGLE', null, 'الکترود کم‌هیدروژن پس از پخت باید در آون نگهدارنده گرم نگه داشته شود تا رطوبت جذب نکند.', 'AWS A5.1 / دستورالعمل سازنده'),
  ('welding_inspector', 'ناهم‌ترازی', 1, 'ناهم‌ترازی (Hi-Lo) رایج مجاز لبه‌ها قبل از جوشکاری ریشه در خطوط لوله حدوداً چقدر است؟', '["حدود ۱٫۶ میلی‌متر","حدود ۵ میلی‌متر","حدود ۳ میلی‌متر","حدود ۰٫۱ میلی‌متر"]'::jsonb, 0, 'SINGLE', null, 'مشخصات جوش‌پذیری معمول (API 1104 و API 5L) حدود ۱/۱۶ in را برای ناهم‌ترازی توصیه می‌کنند.', 'API 1104 (Welding of Pipelines and Related Facilities)')
) as v(job_role, topic, difficulty, stem_fa, options, correct_option, item_type, answer_key, explanation_fa, standard_ref)
where not exists (select 1 from comp_mcq_questions e where e.job_role = v.job_role and e.stem_fa = v.stem_fa);
